    18  /* This standalone module implements deflate / inflate streams */
    19
    20  #ifndef UWS_PERMESSAGEDEFLATE_H
    21  #define UWS_PERMESSAGEDEFLATE_H
    22
    23  #include <cstdint>
    24
    25  /* We always define these options no matter if ZLIB is enabled or not */
    26  namespace uWS {
    27      /* Compressor mode is HIGH8(windowBits), LOW8(memLevel) */
    28      enum CompressOptions : uint32_t {
    29          DISABLED = 0,
    30          SHARED_COMPRESSOR = 1,
    31          DEDICATED_COMPRESSOR_3KB = 9 << 8 | 1,
    32          DEDICATED_COMPRESSOR_4KB = 9 << 8 | 2,
    33          DEDICATED_COMPRESSOR_8KB = 10 << 8 | 3,
    34          DEDICATED_COMPRESSOR_16KB = 11 << 8 | 4,
    35          DEDICATED_COMPRESSOR_32KB = 12 << 8 | 5,
    36          DEDICATED_COMPRESSOR_64KB = 13 << 8 | 6,
    37          DEDICATED_COMPRESSOR_128KB = 14 << 8 | 7,
    38          DEDICATED_COMPRESSOR_256KB = 15 << 8 | 8,
    39          /* Same as 256kb */
    40          DEDICATED_COMPRESSOR = 15 << 8 | 8
    41      };
    42  }
