    44  #if !defined(UWS_NO_ZLIB) && !defined(UWS_MOCK_ZLIB)
    45  #include <zlib.h>
    46  #endif
    47
    48  #include <string>
    49  #include <optional>
    50
    51  #ifdef UWS_USE_LIBDEFLATE
    52  #include "libdeflate.h"
    53  #include <cstring>
    54  #endif
    55
    56  namespace uWS {
    57
    58  /* Do not compile this module if we don't want it */
    59  #if defined(UWS_NO_ZLIB) || defined(UWS_MOCK_ZLIB)
    60  struct ZlibContext {};
    61  struct InflationStream {
    62      std::optional<std::string_view> inflate(ZlibContext *zlibContext, std::string_view compressed, size_t maxPayloadLength) {
    63          return compressed.substr(0, std::min(maxPayloadLength, compressed.length()));
    64      }
    65  };
    66  struct DeflationStream {
    67      std::string_view deflate(ZlibContext *zlibContext, std::string_view raw, bool reset) {
    68          return raw;
    69      }
    70      DeflationStream(int compressOptions) {
    71      }
    72  };
    73  #else
    74
    75  #define LARGE_BUFFER_SIZE 1024 * 16 // todo: fix this
    76
    77  struct ZlibContext {
    78      /* Any returned data is valid until next same-class call.
    79       * We need to have two classes to allow inflation followed
    80       * by many deflations without modifying the inflation */
    81      std::string dynamicDeflationBuffer;
    82      std::string dynamicInflationBuffer;
    83      char *deflationBuffer;
    84      char *inflationBuffer;
    85
    86  #ifdef UWS_USE_LIBDEFLATE
    87      libdeflate_decompressor *decompressor;
    88      libdeflate_compressor *compressor;
    89  #endif
    90
    91      ZlibContext() {
    92          deflationBuffer = (char *) malloc(LARGE_BUFFER_SIZE);
    93          inflationBuffer = (char *) malloc(LARGE_BUFFER_SIZE);
    94
    95  #ifdef UWS_USE_LIBDEFLATE
    96          decompressor = libdeflate_alloc_decompressor();
    97          compressor = libdeflate_alloc_compressor(6);
    98  #endif
    99      }
   100
   101      ~ZlibContext() {
   102          free(deflationBuffer);
   103          free(inflationBuffer);
   104
   105  #ifdef UWS_USE_LIBDEFLATE
   106          libdeflate_free_decompressor(decompressor);
   107          libdeflate_free_compressor(compressor);
   108  #endif
   109      }
   110  };
