   112  struct DeflationStream {
   113      z_stream deflationStream = {};
   114
   115      DeflationStream(CompressOptions compressOptions) {
   116
   117          /* Sliding inflator should be about 44kb by default, less than compressor */
   118
   119          /* Memory usage is given by 2 ^ (windowBits + 2) + 2 ^ (memLevel + 9) */
   120          int windowBits = -(int) ((compressOptions & 0xFF00) >> 8), memLevel = compressOptions & 0x00FF;
   121
   122          //printf("windowBits: %d, memLevel: %d\n", windowBits, memLevel);
   123
   124          deflateInit2(&deflationStream, Z_DEFAULT_COMPRESSION, Z_DEFLATED, windowBits, memLevel, Z_DEFAULT_STRATEGY);
   125      }
   126
   127      /* Deflate and optionally reset. You must not deflate an empty string. */
   128      std::string_view deflate(ZlibContext *zlibContext, std::string_view raw, bool reset) {
   129
   130  #ifdef UWS_USE_LIBDEFLATE
   131          /* Run a fast path in case of shared_compressor */
   132          if (reset) {
   133              size_t written = 0;
   134              static unsigned char buf[1024 + 1];
   135
   136              written = libdeflate_deflate_compress(zlibContext->compressor, raw.data(), raw.length(), buf, 1024);
   137
   138              if (written) {
   139                  memcpy(&buf[written], "\x00", 1);
   140                  return std::string_view((char *) buf, written + 1);
   141              }
   142          }
   143  #endif
   144
   145          /* Odd place to clear this one, fix */
   146          zlibContext->dynamicDeflationBuffer.clear();
   147
   148          deflationStream.next_in = (Bytef *) raw.data();
   149          deflationStream.avail_in = (unsigned int) raw.length();
   150
   151          /* This buffer size has to be at least 6 bytes for Z_SYNC_FLUSH to work */
   152          const int DEFLATE_OUTPUT_CHUNK = LARGE_BUFFER_SIZE;
   153
   154          int err;
   155          do {
   156              deflationStream.next_out = (Bytef *) zlibContext->deflationBuffer;
   157              deflationStream.avail_out = DEFLATE_OUTPUT_CHUNK;
   158
   159              err = ::deflate(&deflationStream, Z_SYNC_FLUSH);
   160              if (Z_OK == err && deflationStream.avail_out == 0) {
   161                  zlibContext->dynamicDeflationBuffer.append(zlibContext->deflationBuffer, DEFLATE_OUTPUT_CHUNK - deflationStream.avail_out);
   162                  continue;
   163              } else {
   164                  break;
   165              }
   166          } while (true);
   167
   168          /* This must not change avail_out */
   169          if (reset) {
   170              deflateReset(&deflationStream);
   171          }
   172
   173          if (zlibContext->dynamicDeflationBuffer.length()) {
   174              zlibContext->dynamicDeflationBuffer.append(zlibContext->deflationBuffer, DEFLATE_OUTPUT_CHUNK - deflationStream.avail_out);
   175
   176              return std::string_view((char *) zlibContext->dynamicDeflationBuffer.data(), zlibContext->dynamicDeflationBuffer.length() - 4);
   177          }
   178
   179          /* Note: We will get an interger overflow resulting in heap buffer overflow if Z_BUF_ERROR is returned
   180           * from passing 0 as avail_in. Therefore we must not deflate an empty string */
   181          return {
   182              zlibContext->deflationBuffer,
   183              DEFLATE_OUTPUT_CHUNK - deflationStream.avail_out - 4
   184          };
   185      }
   186
   187      ~DeflationStream() {
   188          deflateEnd(&deflationStream);
   189      }
   190  };
   191
   192  struct InflationStream {
   193      z_stream inflationStream = {};
   194
   195      InflationStream() {
   196          inflateInit2(&inflationStream, -15);
   197      }
   198
   199      ~InflationStream() {
   200          inflateEnd(&inflationStream);
   201      }
   202
   203      /* Zero length inflates are possible and valid */
   204      std::optional<std::string_view> inflate(ZlibContext *zlibContext, std::string_view compressed, size_t maxPayloadLength) {
   205
   206  #ifdef UWS_USE_LIBDEFLATE
   207          /* Try fast path first */
   208          size_t written = 0;
   209          static char buf[1024];
   210
   211          /* We have to pad 9 bytes and restore those bytes when done since 9 is more than 6 of next WebSocket message */
   212          char tmp[9];
   213          memcpy(tmp, (char *) compressed.data() + compressed.length(), 9);
   214          memcpy((char *) compressed.data() + compressed.length(), "\x00\x00\xff\xff\x01\x00\x00\xff\xff", 9);
   215          libdeflate_result res = libdeflate_deflate_decompress(zlibContext->decompressor, compressed.data(), compressed.length() + 9, buf, 1024, &written);
   216          memcpy((char *) compressed.data() + compressed.length(), tmp, 9);
   217
   218          if (res == 0) {
   219              /* Fast path wins */
   220              return std::string_view(buf, written);
   221          }
   222  #endif
   223
   224          /* We clear this one here, could be done better */
   225          zlibContext->dynamicInflationBuffer.clear();
   226
   227          inflationStream.next_in = (Bytef *) compressed.data();
   228          inflationStream.avail_in = (unsigned int) compressed.length();
   229
   230          int err;
   231          do {
   232              inflationStream.next_out = (Bytef *) zlibContext->inflationBuffer;
   233              inflationStream.avail_out = LARGE_BUFFER_SIZE;
   234
   235              err = ::inflate(&inflationStream, Z_SYNC_FLUSH);
   236              if (err == Z_OK && inflationStream.avail_out) {
   237                  break;
   238              }
   239
   240              zlibContext->dynamicInflationBuffer.append(zlibContext->inflationBuffer, LARGE_BUFFER_SIZE - inflationStream.avail_out);
   241
   242
   243          } while (inflationStream.avail_out == 0 && zlibContext->dynamicInflationBuffer.length() <= maxPayloadLength);
   244
   245          inflateReset(&inflationStream);
   246
   247          if ((err != Z_BUF_ERROR && err != Z_OK) || zlibContext->dynamicInflationBuffer.length() > maxPayloadLength) {
   248              return std::nullopt;
   249          }
   250
   251          if (zlibContext->dynamicInflationBuffer.length()) {
   252              zlibContext->dynamicInflationBuffer.append(zlibContext->inflationBuffer, LARGE_BUFFER_SIZE - inflationStream.avail_out);
   253
   254              /* Let's be strict about the max size */
   255              if (zlibContext->dynamicInflationBuffer.length() > maxPayloadLength) {
   256                  return std::nullopt;
   257              }
   258
   259              return std::string_view(zlibContext->dynamicInflationBuffer.data(), zlibContext->dynamicInflationBuffer.length());
   260          }
